"""Паспорта показателей модального окна текущей прибыли."""


def table(text):
    rows = [line.strip().split("|") for line in text.strip().splitlines()]
    assert all(len(row) == len(rows[0]) for row in rows), [
        (i, len(row)) for i, row in enumerate(rows) if len(row) != len(rows[0])
    ]
    return rows


